var autoSaveInput = (typeof autoSave !== "undefined") ? autoSave : null;
if ((autoSaveInput === null || autoSaveInput === undefined) && typeof commit !== "undefined") {
  autoSaveInput = commit;
}
var autoSaveFlag = C8O.util.parseAutoSaveFlag(autoSaveInput, true);
var refreshInput = (typeof refresh !== "undefined") ? refresh : true;
var refreshFlag = C8O.util.toBoolean(refreshInput, true) === true;
var optimizeMutationsInput = (typeof optimizeMutations !== "undefined") ? optimizeMutations : false;
var optimizeMutationsFlag = C8O.util.toBoolean(optimizeMutationsInput, false) === true;
if (optimizeMutationsFlag) {
  autoSaveFlag = false;
  refreshFlag = false;
}

var removal = C8O.dbo.removeObject({ qname: qname });

var parentQNameText = removal.parentQName ? String(removal.parentQName) : "";
var projectNameText = removal.projectName ? String(removal.projectName) : "";
var classNameText = removal.className ? String(removal.className) : "";

deleteInfo = removal;
deleteErrors = Array.isArray(removal.errors) ? removal.errors : [];
deleteAutoSave = autoSaveFlag;
deleteProject = removal.project || null;
deleteSaved = false;
deleteSaveMessage = "";
deleteAutoSaveApplied = autoSaveFlag;
deleteSuccess = Boolean(removal.removed);
deleteParentQName = parentQNameText;
deleteClassName = classNameText;
deleteProjectName = projectNameText;
deleteSummaryRemoved = deleteSuccess ? 1 : 0;
deleteSummaryErrors = deleteErrors.length;
deleteShouldRefresh = refreshFlag && deleteSuccess && parentQNameText.length > 0;

var saveResult = C8O.dbo.saveProjectIfNeeded(deleteProject, deleteAutoSave, deleteErrors);
var savedFlag = saveResult.saved === true;
deleteSaved = savedFlag;
deleteSaveMessage = saveResult.message || "";
deleteAutoSaveApplied = deleteAutoSave;
